1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  describe("quote — base premiums", () => {
6	    it("should return a premium of 5 G for an empty item list (processing fee only)", () => {
7	      const scenario = {
8	        customer: { yearsWithMHPCO: 0 },
9	        steps: [{ op: "quote", items: [] }],
10	      };
11	
12	      const output = runScenario(scenario);
13	
14	      expect(output.results).toEqual([{ premium: 5 }]);
15	    });
16	    it.todo("should charge 100 G base premium for a sword");
17	    it.todo("should charge 60 G base premium for an amulet");
18	    it.todo("should charge 80 G base premium for a staff");
19	    it.todo("should charge 40 G base premium for a potion");
20	    it.todo("should sum the base premiums of several main items");
21	  });
22	
23	  describe("quote — components and building blocks", () => {
24	    it.todo("should charge 25 G base premium per single component");
25	    it.todo("should charge 50 G base premium for 2 runes");
26	    it.todo("should charge 60 G base premium for exactly 3 runes (block applies)");
27	    it.todo("should charge 100 G base premium for 4 runes (no block, block requires exactly 3)");
28	    it.todo("should charge 175 G base premium for 7 runes (no block)");
29	    it.todo("should charge 75 G base premium for 2 runes and 1 moonstone (no block: different types)");
30	    it.todo("should charge 120 G base premium for 3 runes and 3 moonstones (two separate blocks)");
31	  });
32	
33	  describe("quote — item-specific modifiers", () => {
34	    it.todo("should add 50 % of the item's base premium for a cursed item");
35	    it.todo("should add 30 % of the item's base premium for enchantment level 5");
36	    it.todo("should not add the high-enchantment surcharge for enchantment level 4");
37	    it.todo("should add both surcharges for a cursed item with enchantment level 5");
38	    it.todo("should apply the cursed surcharge only to the cursed item's base premium in a multi-item policy (cursed sword + plain amulet)");
39	  });
40	
41	  describe("quote — policy-wide modifiers", () => {
42	    it.todo("should add 10 % first insurance surcharge per item on every quote");
43	    it.todo("should subtract 20 % loyalty discount for a customer with 2 years with MHPCO");
44	    it.todo("should not apply the loyalty discount for a customer with 1 year with MHPCO");
45	    it.todo("should subtract 15 % follow-up discount on the customer's second quote");
46	    it.todo("should not apply the follow-up discount on the customer's first quote");
47	    it.todo("should add the 5 G processing fee at the very end");
48	    it.todo("should round the final premium up (197.5 G becomes 198 G)");
49	  });
50	
51	  describe("quote — integration examples", () => {
52	    it.todo("should charge 165 G for a newcomer's cursed steel sword with enchantment 3");
53	    it.todo("should charge 160 G for a 3-year customer's second quote of a cursed steel sword with enchantment 7");
54	  });
55	
56	  describe("claim — standard reimbursement", () => {
57	    it.todo("should pay 400 G for 500 G damage to a regular sword (deductible of 100 G)");
58	    it.todo("should pay 100 G for 200 G damage to a rune (no enchantment level or material)");
59	    it.todo("should apply the 100 G deductible once per damage entry (sword 500 G + amulet 300 G pays 600 G)");
60	    it.todo("should round the final payout down (350.5 G becomes 350 G)");
61	  });
62	
63	  describe("claim — special clauses", () => {
64	    it.todo("should reimburse 50 % before the deductible for enchantment level 8 (1000 G damage pays 400 G)");
65	    it.todo("should fully reimburse dragon material before the deductible (800 G damage pays 700 G)");
66	    it.todo("should apply the 50 % rule for a steel sword with enchantment 9 (1000 G damage pays 400 G)");
67	    it.todo("should let the 50 % rule win over dragon material when both apply (dragon sword, enchantment 9, 1000 G damage pays 400 G)");
68	  });
69	
70	  describe("claim — insurance sum and cap", () => {
71	    it.todo("should cap the payout at twice the insurance sum of the policy");
72	    it.todo("should report the remaining cap after a claim");
73	    it.todo("should base the insurance sum on the items' insurance values (sword + amulet = 1600 G, cap 3200 G)");
74	    it.todo("should not raise the cap through premium modifiers (cursed sword still has cap 2000 G)");
75	    it.todo("should not reduce the insurance sum through the component block discount (sword + 3 runes = 1750 G)");
76	    it.todo("should use the insurance sum of both swords for a policy covering two swords (2000 G, cap 4000 G)");
77	    it.todo("should reduce a later payout to the remaining cap (two 1500 G claims on a sword pay 1400 G then 600 G)");
78	  });
79	
80	  describe("claim — multiple items of the same type", () => {
81	    it.todo("should treat two damage entries of the same item type as separate damages with their own deductible");
82	  });
83	
84	  describe("errors", () => {
85	    it.todo("should reject a quote containing an item with an unknown type");
86	    it.todo("should reject a claim whose damage references an item type not covered by the policy");
87	    it.todo("should reject a claim whose damage references an unknown item type");
88	    it.todo("should reject a claim with more damage entries of a type than the policy insures");
89	    it.todo("should reject a claim with a negative damage amount");
